CREATE TEMPORARY VIEW fp_search_base_raw_${grass_region_without_quote} AS
SELECT
    COALESCE(sort_type, 'null') AS sort_type
    ,COALESCE(card_type, 'null') AS card_type 
    ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
    ,location
    ,request_id
    ,rel_raw
    ,rel_add
    ,rel_lx
    ,dt
    ,country
FROM
    srdi_mart.dwd_fp_search_base_1d
WHERE
    dt = ${local_date}
    AND country = ${grass_region}
    AND location < 40
    AND imp_time IS NOT NULL
    AND rel_lx IS NOT NULL
    AND rel_raw IS NOT NULL
    AND rel_raw != 0;

