CREATE TEMPORARY VIEW request_grouped_${grass_region_without_quote} AS
SELECT
    IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__') AS is_ads
    ,MAX(20) AS top_location_type
    ,request_id
    ,SUM(rel_raw) AS rel_raw
    ,SUM(rel_add) AS rel_add
    ,COUNT(1) AS item_imp_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 1 ELSE 0 END) AS irrelevant_cnt
    ,SUM(CASE WHEN rel_lx = 1 THEN 1 ELSE 0 END) AS somewhat_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 4 WHEN rel_lx = 1 THEN 0.5 ELSE NULL END) AS bad_case
FROM
    fp_search_base_raw_${grass_region_without_quote}
WHERE
    location < 20
GROUP BY GROUPING SETS
    (
        (sort_type, card_type, is_ads, request_id),
        (card_type, is_ads, request_id),
        (sort_type, is_ads, request_id),
        (sort_type, card_type, request_id),
        (sort_type, request_id),
        (card_type, request_id),
        (is_ads, request_id),
        (request_id)
    )
UNION ALL
SELECT
    IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__') AS is_ads
    ,MAX(40) AS top_location_type
    ,request_id
    ,SUM(rel_raw) AS rel_raw
    ,SUM(rel_add) AS rel_add
    ,COUNT(1) AS item_imp_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 1 ELSE 0 END) AS irrelevant_cnt
    ,SUM(CASE WHEN rel_lx = 1 THEN 1 ELSE 0 END) AS somewhat_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 4 WHEN rel_lx = 1 THEN 0.5 ELSE NULL END) AS bad_case
FROM
    fp_search_base_raw_${grass_region_without_quote}
WHERE
    location < 40
GROUP BY GROUPING SETS
    (
        (sort_type, card_type, is_ads, request_id),
        (card_type, is_ads, request_id),
        (sort_type, is_ads, request_id),
        (sort_type, card_type, request_id),
        (sort_type, request_id),
        (card_type, request_id),
        (is_ads, request_id),
        (request_id)
    );

