INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_rel_score_metrics_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    sort_type
    ,card_type
    ,is_ads
    ,top_location_type
    ,1.0 * SUM(rel_raw) / SUM(item_imp_cnt) AS item_avg_rel_raw
    ,1.0 * SUM(rel_add) / SUM(item_imp_cnt) AS item_avg_rel_add
    ,AVG(1.0 * rel_raw / item_imp_cnt) AS request_avg_rel_raw
    ,AVG(1.0 * rel_add / item_imp_cnt) AS request_avg_rel_add
    ,1.0 * COUNT(DISTINCT CASE WHEN 1.0 * bad_case / item_imp_cnt > 0.2 THEN request_id END) / COUNT(DISTINCT request_id) AS bad_query_rate
    ,1.0 * SUM(bad_case) / SUM(item_imp_cnt) AS bad_case_rate
    ,1.0 * SUM(irrelevant_cnt) / SUM(item_imp_cnt) AS irrelevant_rate
    ,1.0 * SUM(somewhat_cnt) / SUM(item_imp_cnt) AS somewhat_rate
FROM
    request_grouped_${grass_region_without_quote}
GROUP BY
    1,2,3,4;
